<main class="admin-shell"><?= view('partials/admin_sidebar',['active'=>'entry-tracking']) ?><section class="admin-content"><div class="admin-topbar"><div><span class="eyebrow accent">SCANNER OPERATIONS</span><h1 data-testid="entry-tracking-title">Entry tracking</h1><p>Only QR scan decisions and scanner activity appear here.</p></div><a class="button button-yellow" href="<?= base_url('scanner') ?>">Open scanner ↗</a></div><form class="admin-panel entry-filter-form" method="get" action="<?= base_url('admin/entry-tracking') ?>" data-testid="entry-filter-form"><label>Date<input type="date" name="date" value="<?= esc($filters['date']) ?>" data-testid="entry-date-filter"></label><label>Event<select name="event_id" data-testid="entry-event-filter"><option value="0">All events</option><?php foreach($events as $event): ?><option value="<?= $event['id'] ?>" <?= (int)$filters['event_id']===(int)$event['id']?'selected':'' ?>><?= esc($event['name']) ?></option><?php endforeach ?></select></label><label>Decision<select name="status" data-testid="entry-status-filter"><option value="">All decisions</option><?php foreach(['allowed','duplicate','denied'] as $status): ?><option value="<?= $status ?>" <?= $filters['status']===$status?'selected':'' ?>><?= strtoupper($status) ?></option><?php endforeach ?></select></label><button class="button button-ghost" type="submit">Apply</button></form><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">SCAN DECISIONS</span><h2><?= count($rows) ?> records</h2></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Time</th><th>Participant</th><th>Event / day</th><th>Scanner</th><th>Decision</th><th>Reason</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr data-testid="entry-row-<?= $row['id'] ?>"><td><?= esc($row['attempted_at']) ?></td><td><?= esc($row['participant_name']??'Unknown QR') ?><span class="table-sub"><?= esc($row['registration_id']??'') ?></span></td><td><?= esc($row['event_name']??'—') ?><span class="table-sub"><?= esc(($row['day_label']??'').' '.($row['event_date']??'')) ?></span></td><td><?= esc($row['scanner_name']??'—') ?></td><td><span class="<?= status_class($row['status']) ?>"><?= esc(strtoupper($row['status'])) ?></span></td><td><?= esc($row['reason']) ?></td></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><p class="empty-copy">No scan decisions match these filters.</p><?php endif ?></div></div></section></main>